package com.omnivoice.onspeak47.asr;
import android.content.Context;
import com.larplarpsahur.Io;
import java.util.*;

/** Language is the tag generated by Qwen, not an inference from letter casing. */
public final class QwenFileRecognizer implements AutoCloseable {
    private final QwenAsrNpuEngine engine;
    private QwenFileRecognizer(QwenAsrNpuEngine engine) { this.engine=engine; }
    public static QwenFileRecognizer open(Context context) {
        StreamingAsrEngine e=QwenAsrNpuEngine.tryCreate(context,AsrLanguage.UND);
        if(!(e instanceof QwenAsrNpuEngine)) throw new IllegalStateException("Qwen3-ASR initialization failed. Verify SM8850 model files and QNN runtime; see QwenAsrNpuEngine in logcat.");
        return new QwenFileRecognizer((QwenAsrNpuEngine)e);
    }
    public Recognition transcribe(float[] pcm,Io.Cancellation cancel) throws Exception {
        if(pcm==null||pcm.length<400) throw new IllegalArgumentException("Audio is shorter than 25 ms");
        StringBuilder text=new StringBuilder(); Set<String> languages=new LinkedHashSet<>();
        for(int start=0;start<pcm.length;start+=18*16000) {
            Io.check(cancel);
            float[] block=Arrays.copyOfRange(pcm,start,Math.min(pcm.length,start+18*16000));
            if(block.length<400) block=Arrays.copyOf(block,400);
            String[] result=engine.transcribeFileBlock(block);
            String lang=language(result[0]); if(!"und".equals(lang)) languages.add(lang);
            if(!result[1].trim().isEmpty()) { if(text.length()>0) text.append(' ');text.append(result[1].trim()); }
        }
        return new Recognition(text.toString(),languages.size()==1?languages.iterator().next():languages.size()>1?"mul":"und");
    }
    private static String language(String label) {
        switch(label.toLowerCase(Locale.ROOT)) {
            case "vietnamese":case "vi": return "vi";
            case "english":case "en": return "en";
            case "chinese":case "mandarin":case "zh": return "zh";
            default:return "und";
        }
    }
    @Override public void close() { engine.close(); }
    public static final class Recognition {
        public final String text,sourceLanguage;
        Recognition(String text,String lang) { this.text=text;sourceLanguage=lang; }
    }
}
